#include "actor.h"
#include "../v8-search/mcts.h"
int main(int argc,char**argv){try{if(argc!=6)throw std::runtime_error("MODEL MODE FIRST N OUT");init();Learner base;base.load("training/v7/base.ntd");v9::Net net;std::string mode=argv[2];bool search=mode=="mcts",two=mode=="two";if(!search&&mode!="table"&&!two)net.load(argv[1]);MCTS mc(base);mc.budget=.001;uint32_t first=std::stoul(argv[3]);int n=std::stoi(argv[4]);std::ofstream out(argv[5]);out<<std::setprecision(17);for(int i=0;i<n;i++){uint32_t seed=first+i;RNG rng{seed};Game g;g.reset(rng);Counts c=opening(g);double cpu=0,maxCPU=0;while(!g.over&&high(g.b)<12&&g.turns<6000){double begin=cpuNow();int d=two?-1:search?mc.choose(g.b,g.next,c,uint32_t(seed*2654435761u)^uint32_t(g.turns*2246822519u)).direction:distribution({g.b,g.next,c},base,net,1).greedy;auto a=two?policyTwo(g,base):move(g.b,d);double elapsed=cpuNow()-begin;cpu+=elapsed;maxCPU=std::max(maxCPU,elapsed);if(!a.size)throw std::runtime_error("invalid action");g.advance(a,rng);c=observe(c,g.next);}if(!g.over&&high(g.b)<12)throw std::runtime_error("truncated eval");out<<"{\"seed\":"<<seed<<",\"success\":"<<(high(g.b)>=12?"true":"false")<<",\"moves\":"<<g.turns<<",\"decisionCPU\":"<<cpu<<",\"maxMoveCPU\":"<<maxCPU<<"}"<<std::endl;}}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
